{"file_path":"sales_dashboard/metrics.py","content":""""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """Return the share of sessions whose converted value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """Return the conversion rate pooled across all sessions in all groups."""
    events = [event for group_events in groups.values() for event in group_events]
    return conversion_rate(events)


def conversions_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily_counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def conversion_rate_by_group(groups):
    """Return each group's conversion rate, in ascending group-name order."""
    return {
        name: conversion_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_conversion_streak(daily_counts):
    """Return the longest run of consecutive entries greater than zero."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best
